    from scripts.export_stvg_lite_batch001 import public_source_text
    from scripts.publish_stvg_soft_ep_v1 import verify_privacy
    verify_scaffold();proof=read(BASE/'SCAFFOLD_COMPLETION.json');assert proof['status']=='complete_CPU_scaffold_only' and proof['actual_model_calls']==proof['actual_Student_fits']==proof['new_GT_reads']==0
    out=ROOT/'results/stvg_qwen35_geometry32/2026-10-17/scaffold';out.mkdir(parents=True,exist_ok=False)
